<?php
/** API框架参数集成回归；PHP7.4 CLI，仅使用随机临时配置和合成接口。 */
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$source=dirname(__DIR__,2);$scratch=sys_get_temp_dir().'/mystep-api-settings-'.bin2hex(random_bytes(6));mkdir($scratch,0700);
define('ROOT',$scratch.'/');define('CONFIG',$scratch.'/');define('LIB',$source.'/lib/');define('VENDOR',$source.'/vendor/');define('ROOT_WEB','/sub/');
$_SERVER['DOCUMENT_ROOT']='/';$_SERVER['SCRIPT_NAME']='/sub/index.php';$_SERVER['HTTP_HOST']='fixture.test';
spl_autoload_register(function($name){$file=LIB.$name.'.class.php';if(is_file($file))require_once $file;});
require $source.'/app/myStep/MyStepApiManager.class.php';
$router=(new ReflectionClass('myRouter'))->newInstanceWithoutConstructor();$router->apis=['Hello'=>['read'=>'UnloadedApiCallback::read','other'=>'UnloadedApiCallback::other']];
file_put_contents(CONFIG.'config.php','<?php return '.var_export(['router'=>['mode'=>'rewrite'],'api'=>myApi::httpSettings()],true).';');$ms_setting=new myConfig(CONFIG.'config.php');
if(($argv[1]??'')==='--multipart'){$_SERVER['CONTENT_TYPE']='multipart/form-data; boundary=fixture';myApi::httpBodyLimit(myApi::httpDefaults());exit;}
set_error_handler(function($n,$s,$f,$l){if(error_reporting()&$n)throw new ErrorException($s,0,$n,$f,$l);});$passed=$failed=0;
function same($a,$b){if($a!==$b)throw new RuntimeException('Unexpected result');}
function check($v){if(!$v)throw new RuntimeException('Assertion failed');}
function raises($class,$fn){try{$fn();}catch(Throwable $e){if($e instanceof $class)return $e;throw $e;}throw new LogicException('Expected '.$class);}
function test($name,$run){global $passed,$failed;try{$run();$passed++;echo 'PASS '.$name.PHP_EOL;}catch(Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}}
function policy($extra=[]){return array_replace(['enabled'=>'1','methods'=>'GET,POST','cors'=>'0','admin'=>'0'],$extra);}
try {
 test('framework API group has exactly four global settings',function(){same(['enabled','default_format','body_bytes','domain'],array_keys(myApi::httpSettings()));same(33554432,myApi::httpSettings()['body_bytes']);});
 test('removed global depth and origins cannot be silently persisted',function(){foreach([['json_depth'=>32],['cors_origins'=>[]],['body_bytes'=>0],['body_bytes'=>'32M'],['enabled'=>'true'],['default_format'=>'html']] as $bad)raises(UnexpectedValueException::class,function()use($bad){myApi::httpSettings($bad);});});
 test('dedicated domains accept host and port but reject URLs and wildcard origins',function(){same('api.example.test:8443',myApi::httpSettings(['domain'=>'API.Example.test:8443'])['domain']);foreach(['https://api.example.test','api.example.test/path','*.example.test','u:p@api.example.test','api.example.test:70000',"api.example.test\r\nX: x"] as $bad)raises(UnexpectedValueException::class,function()use($bad){myApi::httpSettings(['domain'=>$bad]);});});
 test('all configured languages expose the same framework API structure',function()use($source){foreach(['default','chs','en'] as $lang){$detail=include $source.'/config/construction/'.$lang.'.php';same(['enabled','default_format','body_bytes','domain'],array_keys($detail['api']['list']));check($detail['api']['list']['domain']['type'][1]===false);}});
 test('existing configuration forms render defaults through myConfig',function()use($source){$c=new myConfig(CONFIG.'config.php');MyStepApiManager::frameworkSettings($c);$list=$c->build($source.'/config/construction/en.php');$html=implode('',array_column($list,'html'));foreach(['enabled','default_format','body_bytes','domain'] as $key)check(strpos($html,'setting[api]['.$key.']')!==false);check(strpos($html,'33554432')!==false);});
 test('dedicated URLs preserve all three routing modes and subdirectory',function(){global $ms_setting;foreach(['rewrite'=>['/sub/api/Hello/read/json','/sub/Hello/read/json'],'path_info'=>['/sub/index.php/api/Hello/read/json','/sub/index.php/Hello/read/json'],'query_string'=>['/sub/index.php?/api/Hello/read/json','/sub/index.php?/Hello/read/json']] as $mode=>$expected){$ms_setting->router->mode=$mode;$ms_setting->api->domain='';same($expected[0],myApi::httpURL('Hello','read'));same(substr($expected[0],0,-5),myApi::httpURL('Hello','read',''));$ms_setting->api->domain='api.example.test';same('http://api.example.test'.$expected[1],myApi::httpURL('Hello','read'));same('http://api.example.test'.substr($expected[1],0,-5),myApi::httpURL('Hello','read',''));}$ms_setting->router->mode='rewrite';$ms_setting->api->domain='';});
 test('domain binding conflicts are rejected before framework configuration is saved',function(){file_put_contents(CONFIG.'domain.php','<?php return ["cms.example.test"=>"CMS"];');$c=new myConfig(CONFIG.'config.php');$c->api->domain='cms.example.test';raises(UnexpectedValueException::class,function()use($c){MyStepApiManager::frameworkSettings($c);});unlink(CONFIG.'domain.php');});
 test('CORS switch admits any valid origin only for the selected registered endpoint',function(){$_SERVER['HTTP_ORIGIN']='https://any.example.test:8443';$c=myApi::httpConfiguration(['endpoints'=>['Hello'=>['read'=>['cors'=>true]]]]);same([$_SERVER['HTTP_ORIGIN']],myApi::httpOrigins('Hello/read/json',$c));same([],myApi::httpOrigins('Hello/other/json',$c));same([],myApi::httpOrigins('Hello/missing/json',$c));foreach(['null','https://example.test/','https://u:p@example.test',"https://x.test\r\nX: 1"] as $bad){$_SERVER['HTTP_ORIGIN']=$bad;same([],myApi::httpOrigins('Hello/read/json',$c));}unset($_SERVER['HTTP_ORIGIN']);});
 test('policy schema rejects unknown callbacks invalid switches and nested methods',function(){foreach([['methods'=>[['GET']]],['cors'=>'yes'],['callback'=>'phpinfo'],['enabled'=>'yes']] as $bad)raises(UnexpectedValueException::class,function()use($bad){myApi::httpConfiguration(['endpoints'=>['Hello'=>['read'=>$bad]]]);});});
 test('old format mode and origin-list fields normalize to the four current settings',function(){$p=myApi::httpConfiguration(['endpoints'=>['Hello'=>['read'=>['mode'=>'request','formats'=>['xml'],'cors_origins'=>['https://old.test']]]]])['endpoints']['Hello']['read'];same(['enabled'=>true,'methods'=>[],'cors'=>false,'admin'=>false],$p);});
 test('catalog display never autoloads callbacks and shows generated addresses',function(){$called=0;$fn=function($name)use(&$called){if($name==='UnloadedApiCallback')$called++;};spl_autoload_register($fn);try{$m=new MyStepApiManager();$rows=$m->entries();same(2,count($rows));same('/sub/api/Hello/other',$rows[0]['url']);same(0,$called);}finally{spl_autoload_unregister($fn);}});
 test('endpoint saves persist only policy and never modify framework parameters',function(){$m=new MyStepApiManager();$before=file_get_contents(CONFIG.'config.php');$m->saveEndpoint('Hello','read',policy(['cors'=>'1']),$m->version);$stored=include CONFIG.'api.php';same(['endpoints'],array_keys($stored));same(true,$stored['endpoints']['Hello']['read']['cors']);same(['enabled','methods','cors','admin'],array_keys($stored['endpoints']['Hello']['read']));same($before,file_get_contents(CONFIG.'config.php'));});
 test('backend exposes only four per-interface controls',function(){$m=new MyStepApiManager();$fields=$m->fields('endpoint','Hello','read');$names=array_column($fields,'name');same(['version','scope','name','policy[enabled]','policy[methods]','policy[cors]','policy[admin]'],$names);});
 test('unregistered callbacks cannot be added through the manager',function(){$m=new MyStepApiManager();raises(InvalidArgumentException::class,function()use($m){$m->saveEndpoint('Hello','phpinfo',policy(),$m->version);});});
 test('stale versions never overwrite another interface policy',function(){$first=new MyStepApiManager();$other=new MyStepApiManager();$other->saveEndpoint('Hello','other',policy(),$other->version);$before=file_get_contents(CONFIG.'api.php');$e=raises(RuntimeException::class,function()use($first){$first->resetEndpoint('Hello','read',$first->version);});same(409,$e->getCode());same($before,file_get_contents(CONFIG.'api.php'));});
 test('legacy globals migrate without silently enabling unrestricted CORS',function(){global $ms_setting;file_put_contents(CONFIG.'api.php','<?php return '.var_export(['enabled'=>false,'default_format'=>'xml','json_bytes'=>4096,'json_depth'=>4,'cors_origins'=>['https://legacy.example.test'],'endpoints'=>[]],true).';');file_put_contents(CONFIG.'config.php','<?php return ["router"=>["mode"=>"rewrite"]];');$ms_setting=new myConfig(CONFIG.'config.php');$c=myApi::httpConfiguration();same(false,$c['enabled']);same(4096,$c['body_bytes']);same([],$c['endpoints']);MyStepApiManager::frameworkSettings($ms_setting);$ms_setting->api->enabled=true;file_put_contents(CONFIG.'config.php','<?php return '.var_export($ms_setting->get(true),true).';');(new MyStepApiManager())->normalizeStorage();$stored=include CONFIG.'api.php';same(['endpoints'],array_keys($stored));same(true,myApi::httpConfiguration()['enabled']);same(4096,myApi::httpConfiguration()['body_bytes']);});
 test('unregistered historical policies can only be removed',function(){global $router;$m=new MyStepApiManager();$m->saveEndpoint('Hello','other',policy(),$m->version);unset($router->apis['Hello']['other']);$m=new MyStepApiManager();same(false,$m->selection('Hello','other'));raises(InvalidArgumentException::class,function()use($m){$m->saveEndpoint('Hello','other',policy(),$m->version);});$m->resetEndpoint('Hello','other',$m->version);check(!isset(myApi::httpConfiguration()['endpoints']['Hello']['other']));});
 test('multipart without declared length is rejected rather than claiming a verified body limit',function(){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,'--multipart'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($p));same('',$err);same('length_required',json_decode($out,true)['error']);});
 test('invalid policy saves and symlinks preserve existing configuration',function(){$m=new MyStepApiManager();$before=file_get_contents(CONFIG.'api.php');raises(InvalidArgumentException::class,function()use($m){$m->saveEndpoint('Hello','read',policy(['cors'=>'yes']),$m->version);});same($before,file_get_contents(CONFIG.'api.php'));rename(CONFIG.'api.php',CONFIG.'original.php');symlink(CONFIG.'original.php',CONFIG.'api.php');raises(UnexpectedValueException::class,function(){new MyStepApiManager();});same($before,file_get_contents(CONFIG.'original.php'));});
} finally {restore_error_handler();foreach(glob(CONFIG.'*') as $file)unlink($file);rmdir($scratch);}
